from __future__ import annotations

import typing

import pytest

from llm_router._internal.capabilities.schema import (
    normalize_schema,
    validate_schema_output,
)

pytestmark = pytest.mark.verification_kind("unit")


class NonDictMapping(typing.Mapping[str, typing.Any]):
    """Mapping implementation that is not a dict subclass."""

    def __init__(self, data: typing.Mapping[str, typing.Any]) -> None:
        self._data = dict(data)

    def __getitem__(self, item: str) -> typing.Any:
        return self._data[item]

    def __iter__(self) -> typing.Iterator[str]:
        return iter(self._data)

    def __len__(self) -> int:
        return len(self._data)


@pytest.mark.verifies("REQ_STRUCTURED_SCHEMA_CONTRACT[revision==2]")
def test_valid_non_dict_mapping_schema_is_accepted_during_normalization() -> None:
    raw_schema = {
        "type": "object",
        "properties": {
            "count": {
                "type": "integer",
                "minimum": 1,
            },
        },
        "required": ["count"],
    }
    mapping_schema = NonDictMapping(raw_schema)

    spec = normalize_schema(mapping_schema)

    assert spec.json_schema == raw_schema
    validation_result = validate_schema_output(spec, {"count": 3})
    assert validation_result.valid is True
